  const sources=new Map(window.TRACK3_SOURCES.map(s=>[s.id,s])),lessons=[],coverage=[];let current;
  function refs(spec){return spec.split(';').map(part=>{const [key,range]=part.split(':'),id=aliases[key];if(!id)throw Error(`Nguồn ${key}`);const pages=range.split(',').flatMap(r=>{const [a,b]=r.split('-').map(Number);return Array.from({length:(b||a)-a+1},(_,i)=>a+i);});return {sourceId:id,pages};});}
  function pageRanges(pages){const pp=[...new Set(pages)].sort((a,b)=>a-b),out=[];for(let i=0;i<pp.length;i++){const start=pp[i];let end=start;while(pp[i+1]===end+1)end=pp[++i];out.push(start===end?`${start}`:`${start}–${end}`);}return out.join(', ');}
  function provenance(spec){const references=refs(spec);return {references,source:references.map(r=>`${sources.get(r.sourceId).title} · tr. ${pageRanges(r.pages)}`).join(' | ')};}
