  U('Playbook evolution và reward hacking','ma:54-60;mb:58-66',['Bài học cần gate trước tái dùng','Giữ grader và eval data độc lập','Tối ưu điểm đo luôn tối ưu giá trị thật','Agent nên xem hidden test để học nhanh'],[0,1],'Context evolution cũng có thể overfit và bị đầu độc.','Curator chọn skill theo điểm test sau khi đã freeze.',['Tách train/dev/test và thời điểm freeze','Review provenance bài học','Đánh giá trên task chưa dùng chọn skill'],'Không rò test và báo tác động xấu cùng tốt.');
  U('Evaluation và lethal trifecta','ma:62-65,68-72;mb:68-81',['Dữ liệu riêng, nguồn không tin và egress có thể nằm ở ba agent','Cần outcome, trajectory và security tests','Tách agent tự loại đường rò dữ liệu','Người duyệt không cần xem payload'],[0,1],'Rủi ro cần xét trên luồng dữ liệu toàn hệ.','Worker đọc web độc hại, lead có secret, tool khác có quyền gửi mail.',['Vẽ dataflow xuyên agent','Chặn kết hợp quyền nguy hiểm','Kiểm payload ở gate cuối'],'Adversarial test không đưa secret qua egress.');
  Q('Async pools và deadline','mb:17-18','Giới hạn ba worker chạy đồng thời bằng cơ chế nào?',['Semaphore hoặc pool có concurrency cap','Thêm câu “chạy ít thôi” vào prompt','Tăng số task vô hạn','Xóa timeout'],'Giới hạn runtime mới cưỡng chế được tải.');
  Q('Permissions và sandbox','ma:36','Khác biệt cốt lõi giữa permission và sandbox?',['Cho phép hành động và cô lập môi trường là hai ranh giới khác nhau','Hai từ cùng chỉ một biến bool','Sandbox luôn thay auth','Permission chỉ để trang trí UI'],'Cần kiểm cả quyền gọi và phạm vi tác động.');
  Q('Playbook evolution và reward hacking','mb:77-80','Vì sao lab cần mốc freeze trước chạy test?',['Ngăn chọn skill hoặc cấu hình theo kết quả test','Để worker không có log','Để giảm kích thước README','Để tăng số agent'],'Nếu chọn theo test, test không còn độc lập.');

  U('Debate và lỗi tương quan','mc:17-19',['Có thể cho agent trả lời độc lập trước critique','Judge vẫn cần bằng chứng và kiểm định','Đa model có thể tăng đa dạng nhưng không bảo đảm đúng','Đa số đồng ý đủ thay ground truth'],[0,1,2],'Collective delusion là nhiều agent cùng sai; tỷ lệ cải thiện trong demo không phải bảo đảm cho mọi task.','Ba critic đồng ý một thông tin sai lấy từ cùng tài liệu.',['Truy lại nguồn thay vì chỉ đếm phiếu','Bổ sung bằng chứng độc lập và case có nhãn','Đo lợi ích với budget và latency tương đương'],'False consensus được phát hiện; báo cả task debate không giúp.');
  U('Chọn framework theo yêu cầu phối hợp','mc:24-25',['State và persistence là tiêu chí cần kiểm','Khả năng debug, tool execution và môi trường deploy ảnh hưởng lựa chọn','Bảng so sánh slide cần kiểm lại theo phiên bản khi triển khai','Một framework luôn tốt nhất cho mọi agent'],[0,1,2],'Các nhãn prototype/production chỉ là gợi ý theo yêu cầu và phiên bản, không phải thuộc tính tuyệt đối.','Đội chọn framework vì bảng slide ghi production nhưng chưa thử resume khi crash.',['Liệt kê yêu cầu state, quyền và recovery','Làm spike cho luồng rủi ro nhất','Đo effort vận hành và test theo contract'],'Workflow qua được recovery và permission tests của dự án.');
  U('Đọc trace và peer review multi-agent','mc:27-31;ma:68-72',['Trace giúp đối chiếu routing với dependency','Cần giải thích worker output và token usage','Benchmark phải so single với multi trên task tương đương','Ảnh trace tự chứng minh chất lượng đáp án'],[0,1,2],'Role clarity, state handoff, failure guards và benchmark là bằng chứng bổ sung nhau.','Writer tạo báo cáo trước khi SearchAgent có kết quả; demo vẫn báo xong.',['Vẽ thứ tự phụ thuộc rồi so trace thực','Sửa join và schema handoff','Chạy lại cùng query và review claim bằng nguồn'],'Writer chỉ tổng hợp sau dữ liệu bắt buộc và báo thiếu khi worker lỗi.');

  T(21,'Fine-tuning LLMs','Từ quyết định có nên tune tới dữ liệu, LoRA/QLoRA, đánh giá và serving.');
  U('Baseline và ROI fine-tuning','ft:6-11;fs:5-7',['Nên so prompt baseline trước','RAG hợp tri thức cập nhật cần nguồn','Fine-tune tự sửa mọi lỗ hổng kiến thức','Loss giảm đủ chứng minh có lãi'],[0,1],'Fine-tuning thay hành vi/phân phối, cần lợi ích đo được.','Đội muốn tune để nhớ bảng giá đổi mỗi ngày.',['Tách lỗi tri thức khỏi hành vi','So RAG và prompt tốt','Tính cost dữ liệu, train và vận hành'],'Eval thực tế cùng cost mỗi task đạt yêu cầu.');
  U('Vòng đời model và di sản base','ft:13-21;fs:8-11',['Tokenizer và architecture được thừa hưởng','Giới hạn base ảnh hưởng adapter','SFT đổi được mọi tokenizer mà không tác động','Active parameters là toàn bộ weights phải lưu'],[0,1],'Checkpoint xuất phát quyết định nhiều ràng buộc của bài toán.','MoE có ít tham số active nhưng vẫn không vừa GPU.',['Tính tổng weights cần chứa','Kiểm runtime hỗ trợ kiến trúc','Chọn base theo task và license'],'Profile memory thực thay vì chỉ nhìn nhãn active.');
  U('Mid-training và domain adaptation','ft:23-29;fs:12-13',['Mid-training là thuật ngữ cần định nghĩa trong ngữ cảnh','Dữ liệu và lịch học có thể khác pretraining','Mọi bài gọi LoRA đều là mid-training','Mở context chỉ cần đổi số config'],[0,1],'Phân loại theo dữ liệu, mục tiêu và compute, không theo tên kỹ thuật.','Đội quảng cáo tăng context mà chưa test dài.',['Xác định năng lực muốn thích nghi','Chọn dữ liệu và objective phù hợp','Eval long-context và giữ năng lực nền'],'Đo retrieval/logic xa, không chỉ nhận input dài.');
  U('CPT SFT và distillation','ft:31-33;fs:14-15',['CPT học phân phối từ văn bản','SFT dùng mẫu đầu vào/đầu ra có giám sát','Distillation học từ teacher','Ba phương pháp luôn dùng cùng loại nhãn'],[0,1,2],'Nguồn dữ liệu và objective quyết định vai trò.','Có hàng triệu tài liệu thô nhưng ít cặp hướng dẫn chuẩn.',['Làm rõ mục tiêu tri thức hay hành vi','So CPT/RAG với SFT phù hợp','Dùng replay/eval để đo quên'],'Không đánh đồng token thô với mẫu instruction.');
  U('On-policy và exposure mismatch','ft:32,101;fs:14,46',['Student có thể gặp state khác teacher','On-policy dùng trajectory của student để nhận phản hồi','Rollout teacher luôn đại diện mọi lỗi student','Teacher mạnh tự bảo đảm student biết phục hồi'],[0,1],'Học trên state không gặp khi chạy thật có thể kém transfer.','Student bắt chước đáp án tốt nhưng sụp sau bước tool sai đầu tiên.',['Thu state student tạo ra','Dùng teacher/verifier phản hồi có review','Eval phục hồi trên rollout mới'],'Đo success nhiều bước ngoài dữ liệu teacher.');
  U('Optimizer và claim thực nghiệm','ft:35-38;fs:16',['Kết quả pretraining không tự suy ra kết quả fine-tune','Đổi optimizer cần ablation cùng điều kiện','Optimizer mới luôn tốt hơn checkpoint cũ','Chỉ tên thuật toán đủ dự báo tốc độ'],[0,1],'Phải kiểm optimizer mismatch, workload và chất lượng cuối.','Đổi AdamW sang optimizer mới làm model quên domain.',['Giữ baseline và hyperparameters rõ','Thử bước cập nhật có kiểm soát','Đo retention cùng task mới'],'Báo compute, config và các metric phụ.');
  U('MoE attention và diffusion','ft:39-41;fs:17-19',['MoE cần xét expert được cập nhật','Kernel khác architecture','Diffusion và autoregressive không có cùng đường sinh','Mọi model đều tune bằng cùng config layer'],[0,1,2],'Architecture và runtime làm thay đổi vị trí tune cùng chi phí.','Config LoRA của dense model không áp đúng cho MoE.',['Inspect modules và expert layout','Xác nhận backend hỗ trợ','Thử gradient và output nhỏ trước'],'Đúng module được train và serving tái hiện được.');
  U('Bộ nhớ full fine-tuning','ft:43-44;fs:20-21',['Weights chỉ là một phần memory','Gradient và optimizer state cũng chiếm chỗ','Mọi setup luôn đúng 16 bytes mỗi tham số','LoRA bỏ hết activation memory'],[0,1],'Ước tính mixed-precision Adam là một cấu hình, không luật chung.','Model weights vừa VRAM nhưng train OOM ngay.',['Phân rã weights, gradients, optimizer, activations','Kiểm precision và batch/seq','Profile peak memory'],'Dự toán kèm giả định và đo peak thực.');
  U('Activations và checkpointing','ft:45,80;fs:20,37-39',['Sequence length ảnh hưởng activations','Checkpointing đổi compute lấy memory','Freeze weights nghĩa không cần backward qua base','Gradient accumulation tự giảm mọi loại memory'],[0,1],'Adapter sâu vẫn cần gradient đi qua các lớp trước đó.','QLoRA vẫn OOM khi tăng sequence length.',['Đo phần activation/logits','Giảm microbatch hoặc length phù hợp','Thử checkpointing và kernel hỗ trợ'],'Quality và throughput được đo sau thay đổi.');
  U('ZeRO FSDP và offload','ft:46-48;al:56',['Sharding phân chia trạng thái train','Offload đổi capacity lấy chi phí truyền dữ liệu','DDP mặc nhiên chia toàn bộ weights','Ít memory luôn đồng nghĩa nhanh hơn'],[0,1],'Nút thắt có thể chuyển sang communication hoặc PCIe.','Nhiều GPU vẫn OOM vì mỗi GPU giữ optimizer đầy đủ.',['Xác định state đang replicate','Chọn mức sharding phù hợp','Profile communication và offload'],'Báo peak memory cùng thời gian mỗi step.');
  U('Bản đồ PEFT','ft:50-51;fs:22',['PEFT giảm phần tham số cần train','Có nhiều họ hơn LoRA','PEFT miễn nhu cầu dataset sạch','Mọi phương pháp tối ưu là optimizer'],[0,1],'Phân biệt parameterization, optimizer, quantization và kernel.','Đội gọi QLoRA và FlashAttention là hai optimizer cạnh tranh.',['Phân loại từng cơ chế','Xác định bottleneck muốn giải','So các tổ hợp tương thích'],'Giải thích cơ chế nào giảm memory hay compute.');
  U('Cơ chế và tham số LoRA','ft:53-55;fs:23-24',['Base thường được freeze','Update dạng BA có rank giới hạn','Trainable params của ma trận là r(d+k)','LoRA phải lưu lại mọi optimizer state của base'],[0,1,2],'Low-rank update giảm state cần học, không xóa base.','Tăng rank mà số trainable params báo không đổi.',['Inspect target modules','Kiểm requires_grad và shapes A/B','Tính số tham số đối chiếu log'],'Gradient chỉ vào phần dự kiến train.');
  U('Target modules và capacity','ft:57-62,67;fs:25-31',['Vị trí gắn adapter ảnh hưởng năng lực','MLP có thể quan trọng ngoài attention','Tăng rank luôn sửa được mọi lỗi dữ liệu','Một kết quả LoRA tương đương full FT đúng cho mọi task'],[0,1],'Thí nghiệm trên slide có điều kiện dữ liệu, module và budget.','Attention-only adapter học kém dù rank lớn.',['Kiểm data và loss mask trước','So phạm vi module cùng budget','Tune LR và rank có ablation'],'Eval task đích và retention trên held-out.');
  U('Learning rate batch và rank','ft:55,59-60,75-76;fs:27-29,35-36',['Cần tune LR theo parameterization','Batch lớn không tự tối ưu chất lượng','Tỷ lệ LR minh họa là chuẩn mọi dataset','Tăng rank luôn cứu LR sai'],[0,1],'Các mức trên slide là điểm thử, không ngưỡng bảo đảm.','GPU dùng ít nên đội tăng batch nhưng eval tệ hơn.',['Giữ baseline số update rõ','Sweep LR và effective batch nhỏ','Theo dõi generalization và cost'],'Chọn bằng held-out thay vì lấp đầy VRAM.');
  U('Các biến thể adapter','ft:64-67;fs:30-31;al:57',['DoRA tách độ lớn và hướng','rsLoRA thay scaling theo rank','PiSSA dùng khởi tạo theo thành phần chính','Tên biến thể mới đảm bảo thắng baseline'],[0,1,2],'Tune baseline tốt và kiểm backend/merge trước chọn biến thể.','Adapter tốt lúc train nhưng merge ra model sai.',['Kiểm support đúng phiên bản','Test equivalence trước/sau merge','So quality và overhead'],'Cùng input cho output hợp sai số cho phép.');
  U('QLoRA và lượng tử hóa','ft:69-72;fs:32-34',['Base có thể được nạp 4-bit trong QLoRA','Adapter dùng precision cao hơn để train','Base 4-bit được cập nhật như full FT trong QLoRA chuẩn','Mọi format lượng tử đều merge được'],[0,1],'Train-time loading và artifact serving là các contract khác nhau.','Model train xong không export được sang backend mong muốn.',['Kiểm format train và serving','Xác minh đường merge/requantize hỗ trợ','Eval lại artifact export'],'Không chỉ kiểm checkpoint trong trainer.');
  U('Kernel logits và loss memory','ft:78-81;fs:37-39;al:55',['Tensor logits có thể tốn nhiều VRAM','Fused/chunked loss có thể giảm materialization','Kernel tốt thay đổi kiến thức model mặc nhiên','Một số đo speedup áp dụng mọi GPU'],[0,1],'Tối ưu implementation cần kiểm tương thích và numeric behavior.','Attention đã tối ưu nhưng tính loss vẫn OOM.',['Profile allocations của logits','Thử loss implementation phù hợp','Kiểm loss/gradient và throughput'],'So numeric sanity cùng peak memory.');
  U('Tooling và experiment tracking','ft:83-87;fs:40-41',['Pin model, tokenizer và config','Theo dõi data version cùng seed','Chỉ lưu checkpoint đủ tái lập mọi run','Feature matrix thay được compatibility test'],[0,1],'Khả năng tái lập thuộc toàn bộ pipeline.','Đồng đội không tái hiện được run có score cao.',['Lưu data/config/runtime versions','Ghi template và mask policy','Có lệnh tái chạy nhỏ'],'Run tái hiện có metric trong khoảng bất định.');
  U('Loss masking và labels','ft:89-90,104,133;fs:42-43,51,65',['Input context không nhất thiết là nhãn cần học','Nên decode phần token được giám sát','Mask sai có thể giám sát zero token','Loss đẹp luôn chứng minh mask đúng'],[0,1,2],'Kiểm mask trực tiếp trước khi dùng GPU nhiều giờ.','Trainer đang dạy model sinh câu hỏi thay vì câu trả lời.',['Decode labels không bị mask','So với assistant spans mong muốn','Kiểm vài batch gồm multi-turn'],'Có số token giám sát đúng và không học tool secret.');
  U('Sequence packing','ft:91-92;fs:44',['Packing giảm padding lãng phí','Ranh giới mẫu và labels cần bảo toàn','Mẫu B nên đọc mọi mẫu A để học nhanh','Packing luôn tương thích labels đã tạo sẵn'],[0,1],'Tăng throughput không được tạo quan hệ giả giữa ví dụ.','Sau packing, output một mẫu phụ thuộc prompt của mẫu trước.',['Kiểm attention boundaries','Kiểm position và alignment labels','So với run không packing'],'Mẫu độc lập không đọc chéo ngoài thiết kế.');
  U('Reasoning template và masked spans','ft:93,124;fs:45,61',['Chat template cần nhất quán train/inference','Vùng reasoning rỗng có thể gây tác động không mong muốn','Mọi model xử lý think tags giống nhau','Accuracy tăng nghĩa reasoning còn nguyên'],[0,1],'Cần kiểm cả format, EOS và năng lực suy luận sau tune.','Model đúng task mới hơn nhưng mất khả năng suy luận nhiều bước.',['Inspect template và spans được học','So cách mask phù hợp model','Eval reasoning và task đích riêng'],'Không chỉ nhìn loss hoặc một accuracy.');
  U('Synthetic data và model collapse','ft:95-101;fs:46-49;al:53-54',['Dữ liệu sinh cần lọc và review','Giữ dữ liệu thật và độ đa dạng là quan trọng','Mọi synthetic data đều gây collapse','Teacher output luôn có quyền sử dụng tự do'],[0,1],'Rủi ro phụ thuộc quy trình sinh, lọc, lặp thế hệ và quyền sử dụng.','Tập train toàn đáp án tự sinh giống nhau làm mất case hiếm.',['Dedupe và kiểm contamination','Giữ real-data anchor và coverage','Eval trên dữ liệu thật riêng'],'Báo chất lượng tail cases và nguồn dữ liệu.');
  U('Trajectory SFT và RL môi trường','ft:103-110;fs:50-54',['Trajectory gồm state/action/observation theo thời gian','Có thể mask bước sai thay vì coi là nhãn tốt','Tool output luôn phải được model học sinh lại','SFT trace và RL trong môi trường là cùng objective'],[0,1],'Phải tách context quan sát được với hành động muốn học.','Model bắt chước cả tool result và hành động sai trong trace.',['Gắn role và spans rõ','Review credit/mask cho bước lỗi','Eval rollout trong môi trường'],'Đo task success và phục hồi sau lỗi.');
  U('Data engine và rubric hacking','ft:112-118;fs:55-57',['Trace thật có thể tạo hard cases','Rubric cũng cần audit chống lách','Dataset bán ngoài luôn phù hợp sản phẩm','Nhiều rollout hơn luôn nhiều mẫu độc lập hơn'],[0,1],'Đơn vị dữ liệu, provenance và chất lượng quan trọng hơn nhãn giá.','Model nêu hàng loạt câu trả lời để lách grader.',['Sửa rubric theo hành vi mục tiêu','Kiểm bằng evidence chứ không keyword','Thêm regression cho kiểu lách'],'Held-out evaluator không thưởng scattergunning.');
  U('Eval và chat-template debugging','ft:120-124,133;fs:58-61,65',['Perplexity không đủ đo task success','Cần so base, prompt baseline và fine-tune','Train loss thấp nhất luôn là model tốt nhất','Không cần test format ở inference'],[0,1],'Loss, protocol và hành vi mục tiêu là các phép kiểm khác nhau.','Training loss tốt nhưng task score gần zero.',['Kiểm template/EOS và tokenizer','Kiểm mask cùng data leakage','Chạy held-out task eval'],'Artifact inference được chấm đúng format thực tế.');
  U('Merge multi-LoRA và serving','ft:126-128;fs:62-63;al:58-59',['Merge và giữ adapter riêng có trade-off','Multi-LoRA cần backend hỗ trợ routing adapter','Cộng adapter luôn bảo toàn mọi kỹ năng','Artifact quantized không cần eval lại'],[0,1],'Serving cần chọn đúng base/adapter/version cho từng request.','Hai tenant nhận nhầm adapter của nhau.',['Gắn identity với adapter registry','Validate base compatibility','Test isolation và fallback'],'Không có cross-tenant adapter leak.');
