  T(22,'DPO ORPO & Alignment','Preference learning, RLHF, GRPO/RLVR, dữ liệu và kiểm định hành vi.');
  U('SFT và alignment','al:5-7',['Demonstration và preference cung cấp tín hiệu khác nhau','Alignment không tự bảo đảm factual correctness','SFT không thể ảnh hưởng style','Aligned model mặc nhiên an toàn mọi hoàn cảnh'],[0,1],'Cách model chọn câu trả lời và tính đúng cần được đo riêng.','Model lịch sự hơn nhưng vẫn bịa chính sách.',['Tách hành vi khỏi tri thức','Dùng nguồn và eval factuality','Đo safety cùng usefulness'],'Không suy correctness từ giọng văn.');
  U('RLHF pipeline','al:9-10,14',['Có thể train reward model từ preference','Policy optimization cần kiểm reward và KL','Reward model là ý kiến con người tuyệt đối','PPO chỉ là SFT đổi tên'],[0,1],'Pipeline nhiều thành phần có chi phí và lỗi riêng.','Policy đạt reward cao nhưng người dùng đánh giá kém.',['Audit reward model','Kiểm reward hacking trên output','So human/held-out evaluation'],'Báo reward cùng chất lượng độc lập.');
  U('DPO và reference log-ratio','al:12-15,28',['DPO dùng chosen/rejected cùng prompt','Công thức chuẩn so log-ratio với reference','DPO chuẩn không cần PPO rollout trong vòng cập nhật','DPO không cần dữ liệu preference'],[0,1,2],'Bỏ explicit reward model không bỏ nhu cầu dữ liệu và đánh giá.','Đội định chạy DPO trên JSON chỉ có prompt và một đáp án.',['Kiểm schema preference pair','Tạo rejected có ý nghĩa và review','Giữ model/template tương thích'],'Batch chứa đúng prompt, chosen, rejected và mask.');
  U('Beta và regularization','al:13,15-16',['Beta tham gia scale log-ratio trong objective','Cần sweep và đo policy drift thực','Beta là accuracy target','Một giá trị beta bảo đảm mọi domain'],[0,1],'Không suy chất lượng cuối chỉ từ một hyperparameter.','Model đổi hành vi quá mạnh sau preference training.',['Kiểm data và reference','Sweep beta cùng learning rate','Đo retention, length và task quality'],'Chọn cấu hình qua held-out, không chỉ reward margin.');
  U('Likelihood displacement và length hacking','al:16,38',['Chosen likelihood giảm có thể là dấu hiệu cần điều tra','Output dài hơn chưa chắc hữu ích hơn','Reward margin tăng chứng minh thắng human eval','Chỉ cần train thêm để hết mọi lỗi preference'],[0,1],'Metrics training tương đối không đủ xác nhận giá trị.','DPO model nói dài và nịnh người dùng hơn.',['Audit preference theo length/style','Kiểm log-prob và response lengths','Eval nội dung bằng rubric độc lập'],'Đo helpfulness, correctness và verbosity riêng.');
  U('Preference pair chất lượng','al:27,32',['Cùng prompt cần cặp so sánh nhất quán','Chosen/rejected phải theo rubric rõ','Đảo nhãn không ảnh hưởng training','Mọi cặp khác độ dài đều là tín hiệu chất lượng'],[0,1],'Nhãn mơ hồ hoặc lệch style dạy sai hành vi.','Annotator chọn câu dài dù chứa thêm dữ kiện sai.',['Định nghĩa rubric ưu tiên đúng nội dung','Review disagreements','Cân coverage và lọc cặp gần như giống'],'Đánh giá agreement và case ngoài phân phối.');
  U('ORPO objective kết hợp','al:21',['ORPO kết hợp SFT và preference objective','Không cần reference model riêng trong công thức ORPO','ORPO chỉ bỏ toàn bộ học có giám sát','Một stage bảo đảm tốt hơn mọi pipeline hai stage'],[0,1],'Single-stage nói về kết hợp mục tiêu, không phải bỏ SFT loss.','Đội mô tả ORPO là preference-only không học chosen response.',['Đọc các thành phần loss','Kiểm dataset và weighting','So SFT+DPO với cùng budget'],'Báo quality, memory và retention thực nghiệm.');
  U('SimPO và KTO','al:19-20',['SimPO dùng reward implicit có chuẩn hóa độ dài','KTO có thể dùng nhãn good/bad không cần cặp cố định','Mọi phương pháp đều cần reference weights','Thumbs-up luôn tương đương ground truth chất lượng'],[0,1],'Dạng nhãn và objective khác nhau; noisy feedback vẫn cần xử lý.','Logs chỉ có dislike nhưng đội ép tạo rejected ngẫu nhiên.',['Xem phương pháp phù hợp dạng nhãn','Kiểm bias và chất lượng feedback','Thử baseline có holdout'],'Không tạo preference giả không có căn cứ.');
  U('GRPO bỏ critic chứ không bỏ mọi reward','al:23-24',['Advantage có thể dựa trên reward tương đối trong nhóm','Không cần value model như PPO thông thường','GRPO cấm sử dụng learned reward model','Chỉ cần sinh nhiều đáp án mà không chấm'],[0,1],'Cơ chế baseline và nguồn reward là hai quyết định riêng.','Đội nói GRPO không cần bất kỳ bộ chấm nào.',['Chỉ rõ reward được tính ở đâu','Kiểm group sampling và advantage','Đo verifier hoặc reward quality'],'Không nhầm bỏ critic với bỏ đánh giá.');
  U('RLVR và verifier','al:24-25,46',['Hợp task có kết quả kiểm được','Verifier sai có thể bị lách','Regex là bằng chứng đủ cho mọi reasoning','RLVR thay toàn bộ preference learning chủ quan'],[0,1],'Verifiability là điều kiện kỹ thuật, không lời bảo đảm.','Model viết đúng format nhưng đáp án sai vẫn được thưởng.',['Tách format và correctness checks','Thêm adversarial tests cho verifier','Eval trên task chưa dùng train'],'Reward không được thưởng lỗi thực thi hoặc đáp án đoán.');
  U('Iterative DPO và distribution shift','al:29-30,44-49',['Dữ liệu mới có thể phản ánh policy hiện tại','Mỗi vòng cần contamination control','Offline pairs ban đầu đại diện mãi mãi','Cứ lặp nhiều vòng là chất lượng tăng đơn điệu'],[0,1],'Vòng dữ liệu cần gate và đối chứng trước/sau.','Policy sinh kiểu lỗi mới không có trong preference ban đầu.',['Thu output mới có quyền sử dụng','Review cặp theo rubric','Dùng held-out riêng cho từng vòng'],'Báo gain, regression và distribution thay đổi.');
  U('Constitutional AI','al:34-35',['Quy tắc explicit giúp tạo critique','Bản sửa vẫn cần kiểm chất lượng','Model tự critique luôn đúng','Constitution loại mọi thiên kiến của người thiết kế'],[0,1],'Nguyên tắc là anchor để đánh giá, không nguồn sự thật tuyệt đối.','AI judge tạo cặp preference theo quy tắc mâu thuẫn.',['Review và ưu tiên nguyên tắc','Audit critique/revision','Kiểm với chuyên gia trên case khó'],'Không dùng cặp lỗi làm nhãn tốt.');
  U('RLAIF và recursion của judge','al:35,41',['AI feedback có thể scale annotation','Judge cần calibration và audit','Dùng hai LLM luôn tạo đánh giá độc lập','RewardBench cao tự chứng minh hợp sản phẩm'],[0,1],'Judge cũng là model có bias và miền áp dụng.','Cả generator và judge cùng bỏ qua lỗi safety.',['Dùng human-labeled audit set','Phân tích correlated errors','Thử judge/rubric khác có kiểm soát'],'Đo failure detection trên case có nhãn.');
  U('Red team và đánh giá alignment','al:36,38-42',['Cần đo helpfulness lẫn safety','Cần test bias và tiếng Việt theo use case','Refusal nhiều hơn luôn an toàn hơn','Một benchmark tổng đủ thay test nội bộ'],[0,1],'Over-refusal và giảm capability cũng là regression.','Model từ chối cả câu hỏi tiếng Việt vô hại.',['Tách allowed và disallowed cases','Đo false refusal theo nhóm','Calibrate rubric bằng người kiểm'],'Giữ usefulness trên request hợp lệ.');
  U('Training strategy theo constraint','al:51-57,60',['CPT, SFT và alignment giải mục tiêu khác nhau','Compute và dữ liệu quyết định phương án','LoRA là một loại dữ liệu preference','Hardware optimization thay nhu cầu eval'],[0,1],'Tách mục tiêu học khỏi cách giảm chi phí thực thi.','Đội thiếu VRAM muốn đổi từ SFT sang DPO chỉ để nhẹ hơn.',['Làm rõ mục tiêu và dataset','Ước lượng memory từng pipeline','Chọn PEFT/quantization tương thích'],'So quality và peak memory của cấu hình thật.');
  U('Model merging và export','al:58-59',['Merge cần kiểm cùng base và interference','Serving artifact phải được eval lại','Cộng mọi adapter tự cộng mọi kỹ năng','Quantization không bao giờ đổi quality'],[0,1],'Kết hợp trọng số không đảm bảo kết hợp hành vi tuyến tính.','Merge math và code adapter làm giảm cả hai tác vụ.',['Kiểm compatibility và weights','So từng tác vụ trước/sau merge','Chọn giữ riêng nếu interference lớn'],'Báo multi-task quality và serving regression.');
  Q('DPO và reference log-ratio','al:13-14','DPO chuẩn thường bỏ thành phần nào so với pipeline RLHF dùng PPO?',['Vòng PPO rollout và explicit reward model riêng trong training đó','Mọi dữ liệu preference','Mọi forward pass qua policy','Mọi reference policy trong công thức chuẩn'],'Objective DPO học trực tiếp từ cặp preference so với reference.');
  Q('ORPO objective kết hợp','al:21','Mô tả đúng về ORPO là gì?',['Kết hợp SFT loss và preference loss trong một objective','Chỉ supervised loss, không preference','Chỉ PPO với critic','Chỉ thay tokenizer'],'Điểm cốt lõi là cách ghép mục tiêu, không lời hứa hơn mọi phương pháp.');
  Q('GRPO bỏ critic chứ không bỏ mọi reward','al:23','GRPO dùng gì để tạo baseline tương đối?',['Reward trong nhóm samples cho cùng prompt','Một danh sách tên tool','Số ký tự trong system prompt','Chỉ token count của model'],'Nguồn reward có thể là verifier hoặc bộ chấm phù hợp task.');
  Q('RLVR và verifier','al:24','Điểm yếu cần kiểm trong RLVR là gì?',['Verifier có đúng và có bị lách không','Tên model có chữ reasoning không','UI có hiển thị reward không','Response có dài hơn baseline không'],'Policy tối ưu tín hiệu chấm; verifier lỗi dẫn tới hành vi sai.');

  T(23,'LangGraph Deep Agents & Orchestration','State graph, durable execution, middleware và hệ thống lai.');
  U('Phổ deterministic–agentic','or:3-11',['Hỏi ai chọn bước tiếp theo để phân loại hệ','Có thể ghép workflow với agent core','Một tool call tự biến hệ thành agent tự chủ hoàn toàn','Agentic hơn luôn tốt hơn'],[0,1],'Mức tự chủ là lựa chọn có giá về chi phí và rủi ro.','Hoàn tiền có luật rõ nhưng điều tra bằng chứng cần bước động.',['Đặt luật trong deterministic shell','Cho agent điều tra trong phạm vi','Gắn approval trước hành động ghi'],'Trace chỉ rõ code hay model quyết ở mỗi bước.');
  U('StateGraph node và edge','or:13-14,21',['Node trả state update theo contract','Edge quyết định đường chạy','Compile gắn runtime/checkpoint theo cấu hình','StateGraph chỉ là prompt dài'],[0,1,2],'Graph làm control flow trở thành artifact kỹ thuật.','Node sửa trực tiếp biến global thay vì trả state update.',['Định nghĩa schema state','Tách node và update rõ','Kiểm edges cùng terminal paths'],'Test từng nhánh và state sau node.');
  U('Super-step và reducer','or:15-16',['Node song song có thể đọc cùng snapshot','Reducer cần định nghĩa cách gộp update','Node đồng thời mặc nhiên thấy update chưa commit của nhau','Append mọi thứ luôn idempotent'],[0,1],'Gộp concurrent writes cần semantics phù hợp và xét retry.','Hai node cùng ghi evidence và runtime báo concurrent update.',['Định nghĩa reducer phù hợp','Giữ ID evidence để dedupe','Test thứ tự và retry'],'Không mất hoặc nhân evidence sau khôi phục.');
  U('Send và Command','or:17-18',['Send hỗ trợ fan-out động với input riêng','Command có thể update state cùng routing','Send bỏ nhu cầu reducer kết quả','Command cho phép bỏ authorization'],[0,1],'Routing động vẫn nằm trong contract graph.','Số đơn cần kiểm chỉ biết lúc runtime.',['Fan-out theo danh sách đơn','Gộp kết quả có khóa','Route nhánh sau theo dữ kiện'],'Mỗi đơn xử lý đúng một kết quả logic.');
  U('Recursion retry timeout và cache','or:19-20',['Step limit không đồng nghĩa token limit','Retry và timeout cần cấu hình theo lỗi','Sync checkpoint bỏ nhu cầu giới hạn loop','Cache node không cần xét input/state'],[0,1],'Giới hạn runtime cần hiểu đúng đơn vị được đếm.','Agent có mười lăm tool calls nhưng dừng trước limit hai mươi lăm steps.',['Đọc số model/tool super-steps','Chọn limit theo graph thực','Vẫn giữ token và time budget'],'Test đúng số bước thay vì suy từ tool count.');
  U('Durability và checkpointer','or:23-25',['Chế độ lưu đổi latency với khả năng khôi phục','Persistent saver cần cho recovery qua process','In-memory saver bảo đảm qua crash máy','Sync persistence làm external API exactly-once'],[0,1],'Persisted state không thay transaction hoặc idempotency của side effect.','Server crash giữa hai bước tài chính.',['Chọn storage và durability theo rủi ro','Kiểm checkpoint đã commit','Dùng idempotency cho API ngoài'],'Crash test không mất state ngoài mức chấp nhận.');
  U('Pending writes và partial recovery','or:25',['Kết quả node đã xong có thể được lưu để tránh chạy lại','Node lỗi cần cơ chế resume đúng','Mọi node phải chạy lại từ đầu bất kể checkpoint','Checkpoint tự phục hồi mọi external state'],[0,1],'Khôi phục cần hiểu ranh giới commit của runtime và tool.','Một trong ba node song song timeout sau hai node hoàn tất.',['Inspect checkpoint/pending writes','Retry phần lỗi theo contract','Kiểm side effect từng node'],'Không lặp tác động của node đã hoàn thành.');
  U('Interrupt và replay node','or:26-28',['Resume có thể chạy lại node từ đầu','Hành động trước interrupt có thể bị lặp','Interrupt giữ nguyên process chờ reviewer','Approved text bất kỳ tự hợp lệ mọi payload'],[0,1],'Vị trí side effect và quyền resume phải được thiết kế.','Email thông báo bị gửi lại mỗi lần resume approval.',['Tách notification idempotent khỏi node ngắt','Gắn approval với payload/version','Kiểm quyền người resume'],'Một approval không tạo nhiều email hay giao dịch.');
  U('Time travel và fork','or:29',['Fork tạo nhánh state mới','Replay có thể gọi lại tool/model','Quay checkpoint tự hoàn tác giao dịch ngoài','Update state luôn xóa lịch sử cũ'],[0,1],'Lịch sử tính toán khác lịch sử tác động ngoài hệ thống.','Reviewer replay run đã hoàn tiền.',['Xác định side effects đã xảy ra','Dùng idempotency và sandbox replay','Không gọi write API ngoài ý định'],'Replay không hoàn tiền lần hai.');
  U('Thread state và cross-thread Store','or:23,30',['Thread_id định danh tiến độ run','Store có thể namespace memory xuyên thread','Thread ID là authorization token','Mọi user được xem checkpoint nếu biết ID'],[0,1],'Identity, persistence và quyền đọc là các lớp riêng.','User đổi thread_id trên request để đọc case của người khác.',['Authorize ownership phía server','Tách namespace user/tenant','Không tin ID do client tự gửi'],'Test truy cập chéo tenant bị chặn.');
